package com.socialblog.interaction.api;import com.socialblog.interaction.application.InteractionService;import com.socialblog.interaction.application.InteractionService.State;import com.socialblog.interaction.domain.TargetType;import com.socialblog.interaction.domain.Interaction;import org.springframework.data.domain.Page;import org.springframework.data.domain.Pageable;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.security.oauth2.jwt.Jwt;import org.springframework.web.bind.annotation.*;import java.util.UUID;import java.util.Base64;@RestController @RequestMapping("/api/v1/interactions")public class InteractionController{private final InteractionService service;public InteractionController(InteractionService s){service=s;}@GetMapping("/{type}/{target}")State get(@PathVariable TargetType type,@PathVariable UUID target,@AuthenticationPrincipal Jwt j){return service.get(j==null?null:UUID.fromString(j.getSubject()),type,target);}@GetMapping("/{type}/{target}/users")Page<Interaction> getLikers(@PathVariable TargetType type,@PathVariable UUID target,Pageable pageable){return service.getLikers(type,target,pageable);}@PutMapping("/{type}/{target}/like")State like(@PathVariable TargetType type,@PathVariable UUID target,@RequestParam(defaultValue="LIKE")String reaction,@AuthenticationPrincipal Jwt j){return service.like(UUID.fromString(j.getSubject()),type,target,reaction);}@DeleteMapping("/{type}/{target}/like")State unlike(@PathVariable TargetType type,@PathVariable UUID target,@AuthenticationPrincipal Jwt j){return service.unlike(UUID.fromString(j.getSubject()),type,target);}@GetMapping("/MEDIA/url")State getMediaInteraction(@RequestParam String b64Url,@AuthenticationPrincipal Jwt j){String url=new String(Base64.getUrlDecoder().decode(b64Url));return service.getMediaState(j==null?null:UUID.fromString(j.getSubject()),url);}@PutMapping("/MEDIA/url/like")State likeMediaUrl(@RequestParam String b64Url,@RequestParam UUID articleId,@RequestParam(defaultValue="LIKE")String reaction,@AuthenticationPrincipal Jwt j){String url=new String(Base64.getUrlDecoder().decode(b64Url));return service.likeMedia(UUID.fromString(j.getSubject()),url,articleId,reaction);}@DeleteMapping("/MEDIA/url/like")State unlikeMediaUrl(@RequestParam String b64Url,@AuthenticationPrincipal Jwt j){String url=new String(Base64.getUrlDecoder().decode(b64Url));return service.unlikeMedia(UUID.fromString(j.getSubject()),url);}}
